def reverse_city_slugs(apps, schema_editor):
    CityServicePage = apps.get_model('core', 'CityServicePage')
    for cp in CityServicePage.objects.all():
        cp.slug = f"{cp.service.slug}-{cp.city}"
        cp.save()


